// FUNCTIONS //

/**
* Asserts that a strided output vector matches a list of expected values, skipping expected values which are `null` (i.e., undefined upon early return).
*
* @private
* @param {Object} t - test object
* @param {Collection} actual - output array
* @param {Array} expected - expected values
* @param {integer} stride - index increment
* @param {NonNegativeInteger} offset - starting index
* @param {string} msg - assertion message prefix
*/
function isEqual( t, actual, expected, stride, offset, msg ) {
	var i;
	for ( i = 0; i < expected.length; i++ ) {
		if ( expected[ i ] === null ) {
			continue;
		}
		t.strictEqual( actual[ offset + ( i*stride ) ], expected[ i ], msg + '[' + i + ']' );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgeequb, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 15', function test( t ) {
	t.strictEqual( dgeequb.length, 15, 'returns expected value' );
	t.end();
});

tape( 'the function computes row and column scale factors (column-major)', function test( t ) {
	var data = COLUMN_MAJOR;
	var info;
	var out;
	var A;
	var R;
	var C;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( data.out );

	info = dgeequb( data.M, data.N, A, data.strideA1, data.strideA2, data.offsetA, R, data.strideR, data.offsetR, C, data.strideC, data.offsetC, out, data.strideOut, data.offsetOut ); // eslint-disable-line max-len
	t.strictEqual( info, data.info, 'returns expected value' );
	isEqual( t, R, data.expected_R, data.strideR, data.offsetR, 'R' );
	isEqual( t, C, data.expected_C, data.strideC, data.offsetC, 'C' );
	isEqual( t, out, data.expected_out, data.strideOut, data.offsetOut, 'out' );
	t.end();
});

